import crypto from 'node:crypto';
import type { Request, Response, NextFunction } from 'express';
import type Redis from 'ioredis';

export interface RawBodyRequest extends Request {
  rawBody?: Buffer;
}

// Bắt buộc gắn vào express.json({ verify }) để giữ nguyên byte gốc trước parse
export function captureRawBody(req: RawBodyRequest, _res: Response, buf: Buffer) {
  if (buf?.length) req.rawBody = Buffer.from(buf);
}

function safeEqualHex(computedHex: string, receivedHex: string): boolean {
  const a = Buffer.from(computedHex.trim().toLowerCase(), 'utf8');
  const b = Buffer.from(receivedHex.trim().toLowerCase(), 'utf8');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function verifyWithRotation(
  secrets: string[],
  computeFn: (secret: string) => string,
  receivedSig: string
): boolean {
  return secrets.filter(Boolean).some((sec) => safeEqualHex(computeFn(sec), receivedSig));
}

export function createWebhookGuard(
  redis: Redis,
  provider: 'meta' | 'zalo_oa' | 'vietqr_sepay',
  secrets: string[],
  maxSkewSeconds = 300
) {
  return async (req: RawBodyRequest, res: Response, next: NextFunction) => {
    if (!req.rawBody) return res.status(400).json({ error: 'MISSING_RAW_BODY' });
    const rawStr = req.rawBody.toString('utf8');

    try {
      let verified = false;
      let eventTsSec = Math.floor(Date.now() / 1000);
      let replayKey = '';

      if (provider === 'meta') {
        const sigHeader = String(req.headers['x-hub-signature-256'] || '');
        const received = sigHeader.replace(/^sha256=/i, '');
        verified = verifyWithRotation(
          secrets,
          (s) => crypto.createHmac('sha256', s).update(req.rawBody!).digest('hex'),
          received
        );
        const parsed = JSON.parse(rawStr);
        replayKey = `wh:meta:${crypto.createHash('sha256').update(rawStr).digest('hex')}`;
        if (parsed?.entry?.[0]?.time) eventTsSec = Number(parsed.entry[0].time);
      } else if (provider === 'zalo_oa') {
        const sigHeader = String(req.headers['x-zevent-signature'] || '');
        const received = sigHeader.replace(/^mac\s*=\s*/i, '');
        const parsed = JSON.parse(rawStr);
        const appId = String(parsed.app_id || parsed.appId || '');
        const tsRaw = Number(parsed.timestamp || 0);
        eventTsSec = tsRaw > 1e12 ? Math.floor(tsRaw / 1000) : tsRaw;
        verified = verifyWithRotation(
          secrets,
          (oaSec) => crypto.createHash('sha256').update(`${appId}${rawStr}${tsRaw}${oaSec}`).digest('hex'),
          received
        );
        replayKey = `wh:zalo:${parsed.event_name || 'ev'}:${parsed.msg_id || received}`;
      } else if (provider === 'vietqr_sepay') {
        const sigHeader = String(req.headers['x-sepay-signature'] || '').replace(/^sha256=/i, '');
        const tsHeader = String(req.headers['x-sepay-timestamp'] || '0');
        eventTsSec = Number(tsHeader);
        verified = verifyWithRotation(
          secrets,
          (s) => crypto.createHmac('sha256', s).update(`${tsHeader}.${rawStr}`).digest('hex'),
          sigHeader
        );
        const parsed = JSON.parse(rawStr);
        replayKey = `wh:vietqr:${parsed.id || parsed.referenceCode || sigHeader}`;
      }

      if (!verified) return res.status(401).json({ error: 'INVALID_WEBHOOK_SIGNATURE' });

      const nowSec = Math.floor(Date.now() / 1000);
      if (Math.abs(nowSec - eventTsSec) > maxSkewSeconds) {
        return res.status(401).json({ error: 'TIMESTAMP_OUT_OF_WINDOW' });
      }

      // Khóa Redis Nonce 24h chống Replay Attack và Retry trùng lặp
      const locked = await redis.set(replayKey, '1', 'EX', 86400, 'NX');
      if (!locked) return res.status(200).json({ status: 'DUPLICATE_IGNORED' });

      return next();
    } catch {
      return res.status(400).json({ error: 'MALFORMED_WEBHOOK_PAYLOAD' });
    }
  };
}
